def f(a: int, b: int) -> bool:
    la = a & 0xFF
    sa = a >> 8
    lb = b & 0xFF
    sb = b >> 8
    if la == 0 or lb == 0:
        return False
    return (sa < sb + lb) and (sb < sa + la)
